import React, { useState, useEffect } from "react";
import { useLocation, Link } from "react-router-dom";
import api from "../utils/api";

const RESOURCE_LINKS = {
  Coursera:     "https://www.coursera.org",
  Udemy:        "https://www.udemy.com",
  "edX":        "https://www.edx.org",
  YouTube:      "https://www.youtube.com",
  "freeCodeCamp": "https://www.freecodecamp.org",
  "Pluralsight": "https://www.pluralsight.com",
  "LeetCode":   "https://www.leetcode.com",
  "HackerRank": "https://www.hackerrank.com",
  "Codecademy": "https://www.codecademy.com",
  LinkedIn:     "https://www.linkedin.com/learning",
};

function ResourceLink({ name }) {
  const href = RESOURCE_LINKS[name] || `https://www.google.com/search?q=${encodeURIComponent(name + " course")}`;
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      className="badge"
      style={{ textDecoration: "none", cursor: "pointer" }}
    >
      {name} ↗
    </a>
  );
}

export default function SkillGap() {
  const routeState = useLocation().state || {};

  const [form, setForm]         = useState({
    target_job_title: routeState.target_job_title || "",
    required_skills:  (routeState.required_skills || []).join(", "),
    job_id:           routeState.job_id || "",
  });
  const [result, setResult]     = useState(null);
  const [loading, setLoading]   = useState(false);
  const [error, setError]       = useState("");
  const [hasProfile, setHasProfile] = useState(true);

  useEffect(() => {
    api.get("/my-profile").catch(() => setHasProfile(false));
    // Auto-run if navigated from job card
    if (routeState.target_job_title) {
      runAnalysis({
        target_job_title: routeState.target_job_title,
        required_skills:  routeState.required_skills || [],
        job_id:           routeState.job_id || "",
      });
    }
  }, []);

  const runAnalysis = async (payload) => {
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const body = payload || {
        target_job_title: form.target_job_title,
        required_skills:  form.required_skills.split(",").map(s => s.trim()).filter(Boolean),
        job_id:           form.job_id || undefined,
      };
      const res = await api.post("/skill-gap", body);
      setResult(res.data);
    } catch (err) {
      const detail = err.response?.data?.detail || "";
      if (detail.includes("Upload")) setHasProfile(false);
      else setError(detail || "Analysis failed.");
    } finally {
      setLoading(false);
    }
  };

  const submitForm = (e) => {
    e.preventDefault();
    runAnalysis();
  };

  const score = result?.readiness_score ?? 0;
  const scoreColor = score >= 70 ? "var(--accent2)" : score >= 40 ? "var(--warn)" : "var(--danger)";

  if (!hasProfile) {
    return (
      <div>
        <div className="page-header"><h1>Skill Gap Analysis</h1></div>
        <div className="card" style={{ textAlign: "center", padding: "48px 32px" }}>
          <div style={{ fontSize: 48, marginBottom: 16 }}>📄</div>
          <h3>Upload your resume first</h3>
          <p className="text-muted" style={{ marginTop: 8, marginBottom: 24 }}>
            We need your skills profile to run the analysis.
          </p>
          <Link to="/profile" className="apply-btn" style={{ display: "inline-flex" }}>Upload Resume</Link>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div className="page-header">
        <h1>Skill Gap Analysis</h1>
        <p>Discover what skills you're missing for your target role — and how to learn them.</p>
      </div>

      {/* Form */}
      <div className="card" style={{ marginBottom: 24 }}>
        <form onSubmit={submitForm}>
          <div className="flex wrap" style={{ gap: 12 }}>
            <div className="form-group" style={{ flex: 2, minWidth: 200, marginBottom: 0 }}>
              <label>Target job title</label>
              <input
                className="form-input"
                placeholder="e.g. Senior Machine Learning Engineer"
                value={form.target_job_title}
                onChange={e => setForm({ ...form, target_job_title: e.target.value })}
                required
              />
            </div>
            <div className="form-group" style={{ flex: 3, minWidth: 240, marginBottom: 0 }}>
              <label>Required skills (comma-separated, optional)</label>
              <input
                className="form-input"
                placeholder="e.g. Python, TensorFlow, MLOps — leave blank to auto-detect"
                value={form.required_skills}
                onChange={e => setForm({ ...form, required_skills: e.target.value })}
              />
            </div>
            <div style={{ display: "flex", alignItems: "flex-end" }}>
              <button className="apply-btn" style={{ padding: "10px 24px", fontSize: 14 }} disabled={loading}>
                {loading ? "Analysing…" : "Analyse"}
              </button>
            </div>
          </div>
        </form>
      </div>

      {error && <div className="alert alert-error" style={{ marginBottom: 16 }}>{error}</div>}

      {loading && (
        <div className="loading-center">
          <div className="spinner" />
          <p style={{ marginTop: 16 }}>AI is analysing your skill gap…</p>
        </div>
      )}

      {result && (
        <div style={{ display: "grid", gap: 16 }}>

          {/* Readiness score */}
          <div className="card">
            <div className="flex justify-between items-center" style={{ marginBottom: 16, flexWrap: "wrap", gap: 12 }}>
              <div>
                <h2>Readiness score</h2>
                <p className="text-muted text-sm" style={{ marginTop: 4 }}>For: {form.target_job_title || routeState.target_job_title}</p>
              </div>
              <div style={{
                width: 80, height: 80, borderRadius: "50%", border: `3px solid ${scoreColor}`,
                display: "flex", alignItems: "center", justifyContent: "center",
                fontFamily: "var(--font-head)", fontWeight: 800, fontSize: 22, color: scoreColor,
              }}>
                {score}%
              </div>
            </div>
            <div className="readiness-bar-wrap">
              <div className="readiness-bar" style={{ width: `${score}%`, background: scoreColor }} />
            </div>
            <p style={{ marginTop: 16, fontSize: 14, color: "var(--muted)", lineHeight: 1.7 }}>
              {result.summary}
            </p>
          </div>

          {/* Matched & Missing */}
          <div className="flex wrap" style={{ gap: 16 }}>
            <div className="card" style={{ flex: 1, minWidth: 220 }}>
              <h3 style={{ marginBottom: 12 }}>
                <span style={{ color: "var(--accent2)" }}>✓</span> Matched skills ({result.matched_skills?.length || 0})
              </h3>
              <div className="skills-list">
                {result.matched_skills?.length > 0
                  ? result.matched_skills.map(s => <span key={s} className="badge green">{s}</span>)
                  : <span className="text-muted text-sm">None matched</span>}
              </div>
            </div>
            <div className="card" style={{ flex: 1, minWidth: 220 }}>
              <h3 style={{ marginBottom: 12 }}>
                <span style={{ color: "var(--danger)" }}>✗</span> Missing skills ({result.missing_skills?.length || 0})
              </h3>
              <div className="skills-list">
                {result.missing_skills?.length > 0
                  ? result.missing_skills.map(s => <span key={s} className="badge danger">{s}</span>)
                  : <span className="text-muted text-sm">No gaps found!</span>}
              </div>
            </div>
          </div>

          {/* Learning roadmap */}
          {result.recommended_learning?.length > 0 && (
            <div className="card">
              <h3 style={{ marginBottom: 16 }}>📚 Learning roadmap</h3>
              <div style={{ display: "grid", gap: 16 }}>
                {result.recommended_learning.map((item, i) => (
                  <div key={i} style={{
                    padding: "16px 20px", borderRadius: "var(--radius-sm)",
                    background: "var(--bg)", border: "1px solid var(--border2)"
                  }}>
                    <div className="flex justify-between items-center" style={{ marginBottom: 6, flexWrap: "wrap", gap: 8 }}>
                      <span style={{ fontFamily: "var(--font-head)", fontWeight: 700 }}>
                        {i + 1}. {item.skill}
                      </span>
                      <span className="badge danger">Missing</span>
                    </div>
                    {item.why && (
                      <p style={{ fontSize: 13, color: "var(--muted)", marginBottom: 10, lineHeight: 1.6 }}>
                        {item.why}
                      </p>
                    )}
                    {item.resources?.length > 0 && (
                      <div className="flex wrap" style={{ gap: 6 }}>
                        <span className="text-muted text-sm" style={{ alignSelf: "center" }}>Learn via:</span>
                        {item.resources.map(r => <ResourceLink key={r} name={r} />)}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

        </div>
      )}
    </div>
  );
}
